import { test, expect } from '@playwright/test';

test.describe('Form Submission with Confirmation Email', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should successfully submit form and send confirmation email', async ({ page }) => {
    // Setup intercept for form submission API
    await page.route('**/api/form/submit', (route) => {
      route.continue();
    });

    // Fill out form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('Hello, this is a test message');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success message
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify confirmation email is sent
    const emailSentNotification = page.getByText('Confirmation email sent');
    await expect(emailSentNotification).toBeVisible();

    // Verify email content
    const emailBody = page.getByText('Thank you for your message, John Doe');
    await expect(emailBody).toBeVisible();

    // Verify email subject
    const emailSubject = page.getByText('Confirmation - Your Message');
    await expect(emailSubject).toBeVisible();

    // Verify email was sent to the correct address
    const emailFrom = page.getByText('john.doe@example.com');
    await expect(emailFrom).toBeVisible();
  });

  test('should handle form submission failure and display error message', async ({ page }) => {
    // Setup intercept for form submission API with error response
    await page.route('**/api/form/submit', (route) => {
      route.abort('failed');
    });

    // Fill out form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane.smith@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message with an error');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message
    const errorMessage = page.getByText('Form submission failed');
    await expect(errorMessage).toBeVisible();

    // Verify error details
    const errorDetail = page.getByText('Email address is required');
    await expect(errorDetail).toBeVisible();

    // Verify form fields are still visible
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toBeVisible();

    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Verify email was not sent
    const emailSentNotification = page.getByText('Confirmation email sent');
    await expect(emailSentNotification).not.toBeVisible();
  });
});
